<?php
namespace app\controller;use app\BaseController;use app\service\AdminAccess;use app\service\QuotaLotService;use think\facade\Db;use think\facade\Session;use think\facade\View;
class Users extends BaseController{
 private function quotaSig(array $u):string{$secret=trim((string)@file_get_contents((string)(getenv('LUMEN_INTEGRITY_KEY_FILE')?:'/www/server/lumenapi/integrity.key')));return hash_hmac('sha256',$u['id'].'|'.($u['quota_total']===null?'NULL':$u['quota_total']).'|'.$u['quota_used'],$secret);}
 private function quotaIntegrityOk(array $u):bool{return !empty($u['quota_integrity_hash'])&&hash_equals((string)$u['quota_integrity_hash'],$this->quotaSig($u));}
 private function lockIntegrity(int $id,string $reason):void{Db::name('users')->where('id',$id)->update(['integrity_locked'=>1,'integrity_reason'=>mb_substr($reason,0,500),'integrity_locked_at'=>date('Y-m-d H:i:s'),'status'=>0,'key_status'=>0,'updated_at'=>date('Y-m-d H:i:s')]);}
private function guard(){return AdminAccess::guard();} private function ownerGuard(){return AdminAccess::ownerGuard();}private function log($a,$id,$d=''){Db::name('audit_logs')->insert(['admin_id'=>Session::get('lumen_admin_id'),'action'=>$a,'target_type'=>'user','target_id'=>$id,'detail'=>$d,'ip'=>request()->ip(),'created_at'=>date('Y-m-d H:i:s')]);}
 public function index(){if($r=$this->guard())return$r;$q=trim((string)input('get.q',''));$b=Db::name('users')->alias('u')->leftJoin('admins a','a.user_id=u.id AND a.status=1')->field('u.*,a.id admin_id,a.role admin_role,(SELECT COUNT(*) FROM api_keys k WHERE k.user_id=u.id AND k.status=1) active_keys');if($q!=='')$b->whereLike('u.username|u.email','%'.$q.'%');View::assign(['items'=>$b->order('u.id','desc')->limit(200)->select()->toArray(),'username'=>Session::get('lumen_admin_username'),'q'=>$q]);return View::fetch(root_path().'view/admin/users.html');}
 public function detail($id){if($r=$this->guard())return$r;$u=Db::name('users')->where('id',(int)$id)->find();if(!$u)return response('Not Found',404);$keys=Db::name('keys')->where('user_id',(int)$id)->order('id','desc')->select()->toArray();foreach($keys as &$k){$k['quota_total']=$u['quota_total'];$k['quota_used']=(int)$u['quota_used'];}unset($k);View::assign(['item'=>$u,'keys'=>$keys,'username'=>Session::get('lumen_admin_username'),'newKey'=>Session::pull('admin_user_new_key','')]);return View::fetch(root_path().'view/admin/user_detail.html');}
 public function toggle($id){if($r=$this->guard())return$r;$id=(int)$id;$u=Db::name('users')->where('id',$id)->find();if(!$u)return response('Not Found',404);$scope=(string)input('post.scope','account');$action=(string)input('post.action','ban');$reason=trim((string)input('post.reason',''));if(!in_array($scope,['account','key','both'],true)||!in_array($action,['ban','unban'],true))return response('Invalid action',422);if($action==='unban'&&!empty($u['integrity_locked']))return response('该账户处于额度完整性锁定，普通解封不可解除。',403);if($action==='unban'&&in_array($scope,['key','both'],true)&&(int)($u['penalty_debt']??0)>0)return response('该账户存在未结清处罚，不能解封 Key。',403);if($action==='ban'&&$reason==='')return response('封禁原因必填',422);$now=date('Y-m-d H:i:s');$data=['updated_at'=>$now];if(in_array($scope,['account','both'],true)){if($action==='ban'){$data['status']=0;$data['ban_reason']=mb_substr($reason,0,500);}else{$data['status']=1;$data['ban_reason']=null;}}if(in_array($scope,['key','both'],true)){if($action==='ban'){$data['key_status']=0;$data['key_ban_reason']=mb_substr($reason,0,500);}else{$data['key_status']=1;$data['key_ban_reason']=null;}}Db::name('users')->where('id',$id)->update($data);\app\service\GatewayCache::forgetUser($id);$this->log('user.'.($action==='ban'?'ban':'unban').'.'.$scope,$id,$reason);return redirect('/admin/users/'.$id);}
 public function unlockIntegrity($id){if($r=$this->guard())return$r;$id=(int)$id;if(trim((string)input('post.confirm',''))!=='UNLOCK')return response('请输入 UNLOCK 确认解除完整性锁',422);$audit=[];Db::transaction(function()use($id,&$audit){$u=Db::name('users')->where('id',$id)->lock(true)->find();if(!$u)throw new \RuntimeException('user');if(empty($u['integrity_locked']))return;$trustedTotal=$u['trusted_quota_total'];$trustedUsed=(int)$u['trusted_quota_used'];$count=max(1,(int)$u['integrity_violation_count']);$penalty=$count*50;$available=$trustedTotal===null?null:max(0,(int)$trustedTotal-$trustedUsed);$deduct=$available===null?0:min($penalty,$available);$debt=max(0,$penalty-$deduct);if($trustedTotal===null){$finalTotal=null;$finalUsed=$trustedUsed;}else{$finalTotal=max($trustedUsed,(int)$trustedTotal-$deduct);$finalUsed=$trustedUsed;}$before=$available;$after=$finalTotal===null?null:max(0,$finalTotal-$finalUsed);$sig=$this->quotaSig(['id'=>$id,'quota_total'=>$finalTotal,'quota_used'=>$finalUsed]);$now=date('Y-m-d H:i:s');Db::name('users')->where('id',$id)->update(['quota_total'=>$finalTotal,'quota_used'=>$finalUsed,'trusted_quota_total'=>$finalTotal,'trusted_quota_used'=>$finalUsed,'integrity_locked'=>0,'integrity_reason'=>null,'integrity_locked_at'=>null,'quota_integrity_hash'=>$sig,'penalty_debt'=>$debt,'status'=>1,'key_status'=>$debt>0?0:1,'ban_reason'=>null,'key_ban_reason'=>null,'updated_at'=>$now]);Db::name('keys')->where('user_id',$id)->update(['quota_total'=>$finalTotal,'quota_used'=>$finalUsed,'updated_at'=>$now]);if($deduct>0&&$finalTotal!==null)QuotaLotService::consume($id,$deduct);if($deduct>0)Db::name('quota_ledger')->insert(['user_id'=>$id,'direction'=>'out','amount'=>$deduct,'source_type'=>'integrity_penalty','source_id'=>Session::get('lumen_admin_id'),'request_id'=>null,'balance_before'=>$before,'balance_after'=>$after,'remark'=>'额度完整性违规处罚（第'.$count.'次，应罚'.$penalty.'，实扣'.$deduct.'）','created_at'=>$now]);$audit=['count'=>$count,'penalty'=>$penalty,'deduct'=>$deduct,'debt'=>$debt,'before'=>$before,'after'=>$after];});\app\service\GatewayCache::forgetUser($id);if($audit)$this->log('user.integrity.unlock',$id,'恢复可信额度并解除完整性锁；第'.$audit['count'].'次违规，应罚='.$audit['penalty'].'，实扣='.$audit['deduct'].'，处罚前余额='.($audit['before']===null?'unlimited':$audit['before']).'，处罚后余额='.($audit['after']===null?'unlimited':$audit['after']).'，待补处罚='.$audit['debt']);return redirect('/admin/users/'.$id);}
 public function quota($id){if($r=$this->guard())return$r;$id=(int)$id;$op=(string)input('post.op');$amount=filter_var(input('post.amount',0),FILTER_VALIDATE_INT);if($amount===false||$amount<0)return response('额度必须为非负整数',422);$audit=[];try{Db::transaction(function()use($id,$op,$amount,&$audit){$u=Db::name('users')->where('id',$id)->lock(true)->find();if(!$u)throw new \RuntimeException('user');if(!empty($u['integrity_locked'])||!$this->quotaIntegrityOk($u))throw new \RuntimeException('integrity_locked_or_invalid');$oldTotal=$u['quota_total']===null?null:(int)$u['quota_total'];$oldAvail=$oldTotal===null?null:max(0,$oldTotal-(int)$u['quota_used']);$debt=(int)($u['penalty_debt']??0);$paid=0;$effective=$amount;if($op==='add'&&$debt>0){$paid=min($amount,$debt);$debt-=$paid;$effective=$amount-$paid;}$total=$oldTotal;if($op==='set')$total=(int)$u['quota_used']+$amount;elseif($op==='add')$total=($total??(int)$u['quota_used'])+$effective;elseif($op==='sub')$total=(int)$u['quota_used']+max(0,($oldAvail??0)-$amount);elseif($op==='unlimited')$total=null;else throw new \RuntimeException('op');$sig=$this->quotaSig(['id'=>$id,'quota_total'=>$total,'quota_used'=>$u['quota_used']]);$now=date('Y-m-d H:i:s');Db::name('users')->where('id',$id)->update(['quota_total'=>$total,'quota_integrity_hash'=>$sig,'trusted_quota_total'=>$total,'trusted_quota_used'=>$u['quota_used'],'penalty_debt'=>$debt,'key_status'=>$debt>0?0:1,'key_ban_reason'=>$debt>0?'账户存在未结清处罚：'.$debt.' 额度':null,'updated_at'=>$now]);Db::name('keys')->where('user_id',$id)->update(['quota_total'=>$total,'quota_used'=>(int)$u['quota_used'],'updated_at'=>$now]);if($debt===0)Db::name('keys')->where('user_id',$id)->where('ban_source','penalty')->update(['status'=>1,'ban_source'=>null,'ban_reason'=>null,'banned_at'=>null,'updated_at'=>$now]);if($paid>0)Db::name('quota_ledger')->insert(['user_id'=>$id,'direction'=>'out','amount'=>$paid,'source_type'=>'penalty_repayment','source_id'=>Session::get('lumen_admin_id'),'request_id'=>null,'balance_before'=>$oldAvail,'balance_after'=>$oldAvail,'remark'=>'新增额度优先偿还完整性处罚欠额 '.$paid,'created_at'=>$now]);$after=$total===null?null:max(0,(int)$total-(int)$u['quota_used']);if($oldAvail!==null&&$after!==null){if($after>$oldAvail)QuotaLotService::createFreeLot($id,'admin_adjust',null,$after-$oldAvail);elseif($after<$oldAvail)QuotaLotService::consume($id,$oldAvail-$after);}if($oldAvail!==$after){$dir=($after===null||($oldAvail!==null&&$after>$oldAvail))?'in':'out';$amt=($oldAvail===null||$after===null)?0:abs($after-$oldAvail);Db::name('quota_ledger')->insert(['user_id'=>$id,'direction'=>$dir,'amount'=>$amt,'source_type'=>'admin_adjust','source_id'=>Session::get('lumen_admin_id'),'request_id'=>null,'balance_before'=>$oldAvail,'balance_after'=>$after,'remark'=>'管理员额度调整：'.$op,'created_at'=>$now]);}$audit=['paid'=>$paid,'debt'=>$debt,'effective'=>$effective];});}catch(\RuntimeException $e){if($e->getMessage()==='integrity_locked_or_invalid')return response('额度完整性异常或已锁定，请先核查完整性记录，不允许直接覆盖可信签名。',409);throw $e;}\app\service\GatewayCache::forgetUser($id);$this->log('user.quota.'.$op,$id,'amount='.$amount.', penalty_paid='.$audit['paid'].', penalty_debt='.$audit['debt'].', credited='.$audit['effective']);return redirect('/admin/users/'.$id);}
 public function adminRole($id){
  if($r=$this->ownerGuard())return$r;
  $id=(int)$id;$action=(string)input('post.action','promote');$u=Db::name('users')->where('id',$id)->find();
  if(!$u)return response('Not Found',404);
  $existing=Db::name('admins')->where('user_id',$id)->find();
  $now=date('Y-m-d H:i:s');
  if($action==='promote'){
   $password=(string)input('post.admin_password','');
   if(strlen($password)<10)return response('管理员密码至少 10 位',422);
   if($existing){
    Db::name('admins')->where('id',$existing['id'])->update(['password_hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>'admin','status'=>1,'updated_at'=>$now]);
    $adminId=(int)$existing['id'];
   }else{
    $base=(string)$u['username'];$username=$base;
    if(Db::name('admins')->where('username',$username)->find())$username=$base.'_admin_'.$id;
    $adminId=Db::name('admins')->insertGetId(['user_id'=>$id,'username'=>$username,'password_hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>'admin','status'=>1,'created_at'=>$now,'updated_at'=>$now]);
   }
   $this->log('user.admin.promote',$id,'admin_id='.$adminId);
  }elseif($action==='demote'){
   if(!$existing)return redirect('/admin/users');
   if(($existing['role']??'admin')==='owner')return response('Owner 不能被降级',403);
   Db::transaction(function()use($existing,$now){
    Db::name('admins')->where('id',$existing['id'])->update(['status'=>0,'updated_at'=>$now]);
    Db::name('keys')->where('admin_id',$existing['id'])->update(['status'=>0,'ban_source'=>'admin','ban_reason'=>'管理员权限已撤销','banned_at'=>$now,'updated_at'=>$now]);
   });
   \app\service\GatewayCache::forgetUser($id);$this->log('user.admin.demote',$id,'admin_id='.$existing['id']);
  }else return response('Invalid action',422);
  return redirect('/admin/users');
 }
 public function resetKey($id){if($r=$this->guard())return$r;$id=(int)$id;$u=Db::name('users')->where('id',$id)->find();if(!$u)return response('Not Found',404);$plain='lmn_'.bin2hex(random_bytes(24));$now=date('Y-m-d H:i:s');Db::transaction(function()use($id,$u,$plain,$now){Db::name('keys')->where('user_id',$id)->where('status',1)->update(['status'=>0,'ban_source'=>'system','ban_reason'=>'管理员重置 Key，旧 Key 已失效','banned_at'=>$now,'updated_at'=>$now]);Db::name('keys')->insert(['user_id'=>$id,'name'=>$u['username'].' Default','key_prefix'=>substr($plain,0,12),'key_hash'=>hash('sha256',$plain),'status'=>((int)($u['penalty_debt']??0)>0?0:1),'ban_source'=>((int)($u['penalty_debt']??0)>0?'penalty':null),'ban_reason'=>((int)($u['penalty_debt']??0)>0?'账户存在未结清处罚':null),'quota_total'=>$u['quota_total'],'quota_used'=>(int)$u['quota_used'],'created_at'=>$now,'updated_at'=>$now]);});\app\service\GatewayCache::forgetUser($id);Session::set('admin_user_new_key',$plain);$this->log('user.api_key.reset',$id,'');return redirect('/admin/users/'.$id);}}
